do $seed$
 <<curriculum>>
 declare author_id uuid; course_id uuid; topic_id uuid; lesson_id uuid; tutorial_id uuid; step_id uuid; file_id uuid; quiz_id uuid; question_id uuid; item jsonb; f jsonb; qu jsonb; criterion jsonb; step_number integer; option_number integer; kind text; data jsonb:='{"objective":"Build a valid document with a descriptive title, main heading and supporting paragraphs.","concepts":"HTML describes the meaning and structure of page content. The document contains a head for metadata and a body for visible elements. Heading levels organize sections; paragraphs hold related sentences. Correct nesting means an inner element closes before its container.","activity":"Build an introduction page about a hobby. Include one main heading and two paragraphs. Change the browser title and explain the difference between the title and visible heading.","lecture":"<h2>Page structure and meaningful text</h2><p>HTML describes the meaning and structure of page content. The document contains a head for metadata and a body for visible elements. Heading levels organize sections; paragraphs hold related sentences. Correct nesting means an inner element closes before its container.</p><h3>Learning objective</h3><p>Build a valid document with a descriptive title, main heading and supporting paragraphs.</p><h3>Try and explain</h3><p>Build an introduction page about a hobby. Include one main heading and two paragraphs. Change the browser title and explain the difference between the title and visible heading.</p><p>Use the generated source alongside the blocks. Save, run, inspect and explain your result.</p><p>Further reading: <a href=\"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content\">MDN learning module</a>.</p>","questions":[["Which element contains visible content?","body","head","title","style"],["Which element represents the main heading?","h1","p","title","br"],["What belongs in a paragraph?","Related text content","A CSS file path only","The whole browser application","A JavaScript variable declaration"]],"files":[{"filename":"index.html","initial":{"blocks":{"languageVersion":0,"blocks":[]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","id":"#Rg]8cVPd;ObhCA0aU?F","x":0,"y":0,"inputs":{"HTML":{"block":{"type":"head","id":"7mFLH$f{Wd|JUzs80fEi","inputs":{"head_element":{"block":{"type":"title","id":"z49h1$NJGgET^/QQ%61d","fields":{"NAME":"My learning page"}}}},"next":{"block":{"type":"body","id":"9dF9RHq|:(wu%]4!fGs~","inputs":{"body_element":{"block":{"type":"heading","id":"h:$vPv_YpQ4N5EUSzy.E","fields":{"LEVEL":"1","TEXT":"My learning page"},"next":{"block":{"type":"paragraph","id":"[zijgpm9*~sTvrG-,=1i","fields":{"TEXT":"I am learning to build websites."},"next":{"block":{"type":"paragraph","id":"bEc/En7khzt)%~]j#=Ng","fields":{"TEXT":"This page describes my interests."}}}}}}}}}}}}}}]}},"code":"<!DOCTYPE html>\n<html>\n  <head>\n      <title>My learning page</title>\n  </head>\n  <body>\n      <h1>My learning page</h1>\n      <p>I am learning to build websites.</p>\n      <p>This page describes my interests.</p>\n  </body>\n</html>\n"}],"checks":[{"type":"htmlExists","selector":"h1","message":"Add a main heading."}]}'::jsonb;
 begin
 select id into author_id from public.profiles where role='admin' order by created_at limit 1;
 if author_id is null then raise exception 'An administrator is required to own the curriculum.'; end if;
 select id into course_id from public.courses where slug='html';
 if course_id is null then insert into public.courses(title,slug,description,color) values('HTML','html','Learn HTML through guided practice and independently reviewed projects.','#4f46e5') returning id into course_id; end if;
 if exists(select 1 from public.topics t where t.course_id=curriculum.course_id and classroom_id is null and title='Page structure and meaningful text' and description like '[WebbedSite curriculum]%') then return; end if;
 insert into public.topics(course_id,title,description,"order",is_published,slug)
 values(course_id,'Page structure and meaningful text','[WebbedSite curriculum] Build a valid document with a descriptive title, main heading and supporting paragraphs.',coalesce((select max("order")+1 from public.topics t where t.course_id=curriculum.course_id and t.classroom_id is null),0),true,'release-html-beginner') returning id into topic_id;
 foreach kind in array array['lecture','tutorial','quiz','laboratory'] loop
 insert into public.lessons(topics_id,author,title,type,is_published,slug,"order",base_xp,proficiency_tier,mastery_checkpoint,learning_objective,topic_track,required_for_topic)
 values(topic_id,author_id,initcap(kind)||': '||'Page structure and meaningful text',kind,false,'release-html-beginner'||'-'||kind,array_position(array['lecture','tutorial','quiz','laboratory'],kind),50,'beginner',kind in ('quiz','laboratory'),'Build a valid document with a descriptive title, main heading and supporting paragraphs.','core',true) returning id into lesson_id;
 if kind='lecture' then insert into public.lectures(lesson_id,content) values(lesson_id,data->>'lecture');
 elsif kind='laboratory' then insert into public.laboratories(lesson_id,instruction) values(lesson_id,jsonb_build_object('description',data->>'activity','files',(select jsonb_agg(jsonb_build_object('filename',f1->>'filename','blocks_json',f1->'initial')) from jsonb_array_elements(data->'files') f1))::text);
 elsif kind='quiz' then
 insert into public.quizzes(lesson_id,time_limit,passing_score) values(lesson_id,300,ceil(jsonb_array_length(data->'questions')*0.75)::integer) returning id into quiz_id;
 for qu in select value from jsonb_array_elements(data->'questions') loop
 insert into public.questions(quiz_id,text,"order") values(quiz_id,qu->>0,coalesce((select max("order")+1 from public.questions qu1 where qu1.quiz_id=curriculum.quiz_id),1)) returning id into question_id;
 for option_number in 1..jsonb_array_length(qu)-1 loop insert into public.options(question_id,text,is_correct) values(question_id,qu->>option_number,option_number=1); end loop;
 end loop;
 else
 insert into public.tutorials(lesson_id,type) values(lesson_id,'block') returning id into tutorial_id;
 for f in select value from jsonb_array_elements(data->'files') loop
 insert into public.block_tutorial_step_files(tutorial_id,filename,file_type,initial_content_json) values(tutorial_id,f->>'filename',split_part(f->>'filename','.',2),f->'initial');
 end loop;
 for step_number in 1..3 loop
 insert into public.block_tutorial_steps(tutorial_id,instruction,hint,"order",highlight_block_type)
 values(tutorial_id,case step_number when 1 then 'Read the objective: '|| (data->>'objective') || E'
Identify the page elements or selector that the activity will use. Start building the demonstrated concept in blocks.' when 2 then 'Build and connect the core behavior or styling. '||(data->>'concepts') else 'Run the complete project, inspect the generated source and check the stated cases. '||(data->>'activity') end,
 'Use the appropriate language palette. Inspect connections and run the preview after each small change.',step_number,case when 'html'='javascript' then 'js_listen' when 'html'='css' then 'style_target' else 'heading' end) returning id into step_id;
 for f in select value from jsonb_array_elements(data->'files') loop
 select id into file_id from public.block_tutorial_step_files f1 where f1.tutorial_id=curriculum.tutorial_id and filename=f->>'filename';
 insert into public.block_tutorial_step_expected(step_id,file_id,expected_code,expected_blocks_json,test_cases,require_block_structure)
 values(step_id,file_id,f->>'code',f->'solution',case when f->>'filename'='index.html' then data->'checks' else '[]'::jsonb end,false);
 end loop;
 end loop;
 end if;
 update public.lessons set is_published=true where id=lesson_id;
 end loop;
 end $seed$;

