ther reading: <a href=\"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content\">MDN learning module</a>.</p>","questions":[["What connects a label to a control?","Matching for and id values","Matching colors","The file name","Their position alone"],["What does a placeholder replace?","Neither a persistent label nor instructions","Every label","Form submission behavior","Keyboard support"],["What should you test when reviewing a form?","Labels and keyboard access","Only background color","Only file size","Only heading font"]],"files":[{"filename":"index.html","initial":{"blocks":{"languageVersion":0,"blocks":[]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","id":"VBu~mXlJ}ntRWyGp2aZI","x":0,"y":0,"inputs":{"HTML":{"block":{"type":"head","id":"`W.POAKTRQ^`1vMkuy_f","inputs":{"head_element":{"block":{"type":"title","id":"P^TRYAJ8j5ZE,xrhdaJP","fields":{"NAME":"My learning page"}}}},"next":{"block":{"type":"body","id":"o;W%rph,Ks_0F$2`Cmb{","inputs":{"body_element":{"block":{"type":"heading","id":"h;)6$U1~$(Z%RTY6WrQ$","fields":{"LEVEL":"1","TEXT":"Contact our club"},"next":{"block":{"type":"paragraph","id":"o$,}TnqX?zr)eo-k`*RG","fields":{"TEXT":"Tell us what you would like to learn."},"next":{"block":{"type":"form","id":"NHsRXX90CZ,vncM,$]=;","fields":{"NOVALIDATE":false},"inputs":{"CONTENT":{"block":{"type":"label","id":"K(H8L!Y|M+jSq?Qp-}2|","fields":{"FOR":"email","TEXT":"Email address"},"next":{"block":{"type":"input","id":"~bXoS8nOnXPvKf0[u]l,","fields":{"NAME":"email","REQUIRED":false,"TYPE":"email","PLACEHOLDER":"Enter text"},"inputs":{"attributes":{"block":{"type":"id","id":"X5EPB[x-,VxTDtvJvh$?","fields":{"NAME":"email"}}}},"next":{"block":{"type":"label","id":")xlRhz6M!t!ex(atr6e2","fields":{"FOR":"message","TEXT":"Your message"},"next":{"block":{"type":"textarea","id":"#pNgoEs9vcS!+PlA^q+H","fields":{"NAME":"message","ROWS":4,"COLS":50,"TEXT":""},"inputs":{"attributes":{"block":{"type":"id","id