 declare author_id uuid; course_id uuid; topic_id uuid; lesson_id uuid; tutorial_id uuid; step_id uuid; file_id uuid; quiz_id uuid; question_id uuid; item jsonb; f jsonb; qu jsonb; criterion jsonb; step_number integer; option_number integer; kind text; data jsonb:='{"objective":"Apply a selector and declarations to improve text readability without changing HTML structure.","concepts":"A CSS rule combines a selector with declarations. The selector chooses elements; each declaration gives a property and value. Start with a small change, run the preview, and observe its effect. Use readable foreground/background combinations and consistent spacing.","activity":"Style a page heading with a readable dark color. Add a second rule for paragraphs. Explain which elements each selector matches and compare the before/after output.","lecture":"<h2>Selectors, properties and readable styling</h2><p>A CSS rule combines a selector with declarations. The selector chooses elements; each declaration gives a property and value. Start with a small change, run the preview, and observe its effect. Use readable foreground/background combinations and consistent spacing.</p><h3>Learning objective</h3><p>Apply a selector and declarations to improve text readability without changing HTML structure.</p><h3>Try and explain</h3><p>Style a page heading with a readable dark color. Add a second rule for paragraphs. Explain which elements each selector matches and compare the before/after output.</p><p>Use the generated source alongside the blocks. Save, run, inspect and explain your result.</p><p>Further reading: <a href=\"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics\">MDN learning module</a>.</p>","questions":[["What does a selector choose?","Elements to style","The project owner","A database table","A quiz answer"],["Which is a CSS property?","color","h1","body","index.html"],["What should you do after a small styling change?","Run the preview and inspect the effect","Delete HTML structure","Assume it worked","Change every rule at once"]],"files":[{"filename":"styles.css","initial":{"blocks":{"languageVersion":0,"blocks":[]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"style_target","id":":bWz4exN`Y-vw}0!%/2x","x":0,"y":0,"fields":{"TARGET":"h1"},"inputs":{"CONTENT":{"block":{"type":"external_text_color","id":"Bl$VUHQzeQ|pC9H)GP[q","fields":{"COLOR":"#17324d"},"next":{"block":{"type":"external_font_weight","id":"!]8_tgw}adO*Y6bBu:bj","fields":{"VALUE":"bold"}}}}}}}]}},"code":"h1 {\n  color: #17324d;\n  font-weight: bold;\n  }"},{"filename":"index.html","initial":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","fields":{},"inputs":{"HTML":{"block":{"type":"head","fields":{},"inputs":{"head_element":{"block":{"type":"head_link","fields":{"TYPE":"stylesheet","URL":"styles.css"}}}},"next":{"block":{"type":"body","fields":{},"inputs":{"body_element":{"block":{"type":"heading","fields":{"TEXT":"My learning page","LEVEL":"1"},"next":{"block":{"type":"div","fields":{},"inputs":{"attributes":{"block":{"type":"class","fields":{"NAME":"cards"}}},"CONTENT":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"HTML"}}}},"next":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"CSS"}}}},"next":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"JavaScript"}}}}}}}}}}}}}}}}}}}}}}]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","fields":{},"inputs":{"HTML":{"block":{"type":"head","fields":{},"inputs":{"head_element":{"block":{"type":"head_link","fields":{"TYPE":"stylesheet","URL":"styles.css"}}}},"next":{"block":{"type":"body","fields":{},"inputs":{"body_element":{"block":{"type":"heading","fields":{"TEXT":"My learning page","LEVEL":"1"},"next":{"block":{"type":"div","fields":{},"inputs":{"attributes":{"block":{"type":"class","fields":{"NAME":"cards"}}},"CONTENT":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"HTML"}}}},"next":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"CSS"}}}},"next":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"JavaScript"}}}}}}}}}}}}}}}}}}}}}}]}},"code":"<!DOCTYPE html>\n<html>\n  <head>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n      <h1>My learning page</h1>\n      <div class=\"cards\">\n        <article>\n          <p>HTML</p>\n        </article>\n        <article>\n          <p>CSS</p>\n        </article>\n        <article>\n          <p>JavaScript</p>\n        </article>\n      </div>\n  </body>\n</html>\n"}],"checks":[{"type":"codeIncludes","value":"color","message":"Include the concept demonstrated in this step."}]}'::jsonb;
 begin
 select id into author_id from public.profiles where role='admin' order by created_at limit 1;
 if author_id is null then raise exception 'An administrator is required to own the curriculum.'; end if;
 select id into course_id from public.courses where slug='css';
 if course_id is null then insert into public.courses(title,slug,description,color) values('CSS','css','Learn CSS through guided practice and independently reviewed projects.','#4f46e5') returning id into course_id; end if;
 if exists(select 1 from public.topics t where t.course_id=curriculum.course_id and classroom_id is null and title='Selectors, properties and readable styling' and description like '[WebbedSite curriculum]%') then return; end if;
 insert into public.topics(course_id,title,description,"order",is_published,slug)
 values(course_id,'Selectors, properties and readable styling','[WebbedSite curriculum] Apply a selector and declarations to improve text readability without changing HTML structure.',coalesce((select max("order")+1 from public.topics t where t.course_id=curriculum.course_id and t.classroom_id is null),0),true,'release-css-beginner') returning id into topic_id;
 foreach kind in array array['lecture','tutorial','quiz','laboratory'] loop
 insert into public.lessons(topics_id,author,title,type,is_published,slug,"order",base_xp,proficiency_tier,mastery_checkpoint,learning_objective,topic_track,required_for_topic)
 values(topic_id,author_id,initcap(kind)||': '||'Selectors, properties and readable styling',kind,false,'release-css-beginner'||'-'||kind,array_position(array['lecture','tutorial','quiz','laboratory'],kind),50,'beginner',kind in ('quiz','laboratory'),'Apply a selector and declarations to improve text readability without changing HTML structure.','core',true) returning id into lesson_id;
 if kind='lecture' then insert into public.lectures(lesson_id,content) values(lesson_id,data->>'lecture');
 elsif kind='laboratory' then insert into public.laboratories(lesson_id,instruction) values(lesson_id,jsonb_build_object('description',data->>'activity','files',(select jsonb_agg(jsonb_build_object('filename',f1->>'filename','blocks_json',f1->'initial')) from jsonb_array_elements(data->'files') f1))::text);
 elsif kind='quiz' then
 insert into public.quizzes(lesson_id,time_limit,passing_score) values(lesson_id,300,ceil(jsonb_array_length(data->'questions')*0.75)::integer) returning id into quiz_id;
 for qu in select value from jsonb_array_elements(data->'questions') loop
 insert into public.questions(quiz_id,text,"order") values(quiz_id,qu->>0,coalesce((select max("order")+1 from public.questions qu1 where qu1.quiz_id=curriculum.quiz_id),1)) returning id into question_id;
 for option_number in 1..jsonb_array_length(qu)-1 loop insert into public.options(question_id,text,is_correct) values(question_id,qu->>option_number,option_number=1); end loop;
 end loop;
 else
 insert into public.tutorials(lesson_id,type) values(lesson_id,'block') returning id into tutorial_id;
 for f in select value from jsonb_array_elements(data->'files') loop
 insert into public.block_tutorial_step_files(tutorial_id,filename,file_type,initial_content_json) values(tutorial_id,f->>'filename',split_part(f->>'filename','.',2),f->'initial');
 end loop;
 for step_number in 1..3 loop
 insert into public.block_tutorial_steps(tutorial_id,instruction,hint,"order",highlight_block_type)
 values(tutorial_id,case step_number when 1 then 'Read the objective: '|| (data->>'objective') || E'
Identify the page elements or selector that the activity will use. Start building the demonstrated concept in blocks.' when 2 then 'Build and connect the core behavior or styling. '||(data->>'concepts') else 'Run the complete project, inspect the generated source and check the stated cases. '||(data->>'activity') end,
 'Use the appropriate language palette. Inspect connections and run the preview after each small change.',step_number,case when 'css'='javascript' then 'js_listen' when 'css'='css' then 'style_target' else 'heading' end) returning id into step_id;
 for f in select value from jsonb_array_elements(data->'files') loop
 select id into file_id from public.block_tutorial_step_files f1 where f1.tutorial_id=curriculum.tutorial_id and filename=f->>'filename';
 insert into public.block_tutorial_step_expected(step_id,file_id,expected_code,expected_blocks_json,test_cases,require_block_structure)
 values(step_id,file_id,f->>'code',f->'solution',case when f->>'filename'='styles.css' then data->'checks' else '[]'::jsonb end,false);
 end loop;
 end loop;
 end if;
 update public.lessons set is_published=true where id=lesson_id;
 end loop;
 end $seed$;

