eloper.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics\">MDN learning module</a>.</p>","questions":[["What is the first step when a rule appears ineffective?","Check matching selectors and competing declarations","Add random properties","Delete the stylesheet","Rename every file"],["What does responsive layout adapt to?","Available viewport or container space","The account password","Only the teacher’s device","The badge count"],["What is useful evidence of a layout fix?","Before/after observations and the relevant rule","XP alone","A file name alone","A copied screenshot without explanation"]],"files":[{"filename":"styles.css","initial":{"blocks":{"languageVersion":0,"blocks":[]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"style_target","id":"74p[J?@8O~:gy;RDR=To","x":0,"y":0,"fields":{"TARGET":".cards"},"inputs":{"CONTENT":{"block":{"type":"external_display","id":"sJcIDbyy1NLZS-_+W[Ne","fields":{"DISPLAY":"flex"},"next":{"block":{"type":"external_flex_wrap","id":"V_)EGoU9mG$c/k}NJI?l","fields":{"VALUE":"wrap"},"next":{"block":{"type":"external_gap","id":"ptJX]#)Ii[k@+D|`g^z^","fields":{"SIZE":"24","UNIT":"px"}}}}}}}}}]}},"code":".cards {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 24px;\n  }"},{"filename":"index.html","initial":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","fields":{},"inputs":{"HTML":{"block":{"type":"head","fields":{},"inputs":{"head_element":{"block":{"type":"head_link","fields":{"TYPE":"stylesheet","URL":"styles.css"}}}},"next":{"block":{"type":"body","fields":{},"inputs":{"body_element":{"block":{"type":"heading","fields":{"TEXT":"My learning page","LEVEL":"1"},"next":{"block":{"type":"div","fields":{},"inputs":{"attributes":{"block":{"type":"class","fields":{"NAME":"cards"}}},"CONTENT":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"paragraph","fields":{"TEXT":"HTML"}}}},"next":{"block":{"type":"article","fields":{},"inputs":{"CONTENT":{"block":{"type":"parag