 declare author_id uuid; course_id uuid; topic_id uuid; lesson_id uuid; tutorial_id uuid; step_id uuid; file_id uuid; quiz_id uuid; question_id uuid; item jsonb; f jsonb; qu jsonb; criterion jsonb; step_number integer; option_number integer; kind text; data jsonb:='{"objective":"Combine a reusable rendering function, a collection and input events into a working filter.","concepts":"An array stores a collection. A rendering function can create the visible list from that collection, while filtering chooses matching entries. Normalize both the query and item names for case-insensitive comparison. Clear previous output before rendering the new list, and test an empty query and a query with no matches.","activity":"Build a searchable list of HTML, CSS and JavaScript topic cards. Render all cards initially, filter as the user types, ignore letter case, show a useful empty state and restore all cards when cleared. Explain how data flows from the input to the rendering function.","lecture":"<h2>Reusable functions, arrays and interactive filtering</h2><p>An array stores a collection. A rendering function can create the visible list from that collection, while filtering chooses matching entries. Normalize both the query and item names for case-insensitive comparison. Clear previous output before rendering the new list, and test an empty query and a query with no matches.</p><h3>Learning objective</h3><p>Combine a reusable rendering function, a collection and input events into a working filter.</p><h3>Try and explain</h3><p>Build a searchable list of HTML, CSS and JavaScript topic cards. Render all cards initially, filter as the user types, ignore letter case, show a useful empty state and restore all cards when cleared. Explain how data flows from the input to the rendering function.</p><p>Use the generated source alongside the blocks. Save, run, inspect and explain your result.</p><p>Further reading: <a href=\"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting\">MDN learning module</a>.</p>","questions":[["How do you compare text without case differences?","Normalize both values consistently","Normalize only the query sometimes","Remove the array","Change the event name"],["Why clear the list before re-rendering?","To avoid accumulating duplicate output","To erase the stored project","To disable filtering","To change HTML syntax"],["Which test checks an important edge case?","A query with no matches","Only the first matching letter","Only the initial view","Only a screenshot of code"]],"files":[{"filename":"main.js","initial":{"blocks":{"languageVersion":0,"blocks":[]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"js_const","id":"%~IJMyOc8fD;uN+uaYnI","x":0,"y":0,"fields":{"NAME":"topics"},"inputs":{"VALUE":{"block":{"type":"js_array_new","id":"HP|Dnj--6_m(JjVj*d|3","extraState":{"itemCount":3},"inputs":{"ITEM0":{"block":{"type":"js_string_val","id":"6EY45k}nNNN8hxEVhfvA","fields":{"VALUE":"HTML"}}},"ITEM1":{"block":{"type":"js_string_val","id":"zzRh$f8+[9CrJt.5{r34","fields":{"VALUE":"CSS"}}},"ITEM2":{"block":{"type":"js_string_val","id":"z/luhi=,rl*hch@J#spq","fields":{"VALUE":"JavaScript"}}}}}}},"next":{"block":{"type":"js_function_def","id":"@Ma[k8Ix2(E+cO:D0Mf_","fields":{"NAME":"renderCards","PARAMS":"query"},"inputs":{"BODY":{"block":{"type":"js_set_inner_html","id":"N%cl)*6/kIkRYqAo8BbN","inputs":{"ELEM":{"block":{"type":"js_get_by_id","id":"-Kh3V3t8zH0a3wzuYs,|","fields":{"ID":"cards"}}},"HTML":{"block":{"type":"js_string_val","id":"^q^r-/MaeMi-:;LK[$8^","fields":{"VALUE":""}}}},"next":{"block":{"type":"js_for_each","id":"2d/Sa^B-5@xFy0K9AchJ","inputs":{"ARR":{"block":{"type":"js_array_transform","id":";NRd6;0L}wH)?UE`7m.5","fields":{"METHOD":"filter"},"inputs":{"ARR":{"block":{"type":"js_get_var","id":"v0w6T!QOB(Qo:iJt(cG)","fields":{"NAME":"topics","PICK_NAME":"__choose__"}}},"CALLBACK":{"block":{"type":"js_callback","id":"!]F)AcPSF;47ZEfaqhT+","fields":{"PARAMS":"name"},"inputs":{"BODY":{"block":{"type":"js_return","id":"VBg~Z}9J0l0E?`JV}.][","inputs":{"VALUE":{"block":{"type":"js_string_includes","id":"I*##?]N_o7u9ioo]4YyF","inputs":{"STR":{"block":{"type":"js_string_case","id":"k(N$K$V1*@D^eoS*OY}w","fields":{"METHOD":"toLowerCase"},"inputs":{"STR":{"block":{"type":"js_get_var","id":"*/}_.qG!X@_cHIRGRs^=","fields":{"NAME":"name","PICK_NAME":"__choose__"}}}}}},"SEARCH":{"block":{"type":"js_string_case","id":":=]l(C!a)WoPmFp$6^vH","fields":{"METHOD":"toLowerCase"},"inputs":{"STR":{"block":{"type":"js_get_var","id":"_F!i8`CmNbM!G?QZh0*r","fields":{"NAME":"query","PICK_NAME":"__choose__"}}}}}}}}}}}}}}}}}},"CALLBACK":{"block":{"type":"js_callback","id":"6A1}Sm4Pp^zF:_F=]c#z","fields":{"PARAMS":"name"},"inputs":{"BODY":{"block":{"type":"js_const","id":"v|iTgBhd4UJL6teZ@bk,","fields":{"NAME":"card"},"inputs":{"VALUE":{"block":{"type":"js_create_element","id":"dNWVO~Y0xkGr|zZx]]EL","fields":{"TAG":"article"}}}},"next":{"block":{"type":"js_set_text_content","id":"DYryKP{CWfi%V#h+J(.*","inputs":{"ELEM":{"block":{"type":"js_get_var","id":"nN$KEYg]$8Cyzh-S7,Np","fields":{"NAME":"card","PICK_NAME":"__choose__"}}},"TEXT":{"block":{"type":"js_get_var","id":".G]uN}TEDY2xxE?L8{Z*","fields":{"NAME":"name","PICK_NAME":"__choose__"}}}},"next":{"block":{"type":"js_append_child","id":"_/QAxv#Pn`sC}e#-QFg:","inputs":{"PARENT":{"block":{"type":"js_get_by_id","id":"`a`f4=MZ[3p~pyT`paZY","fields":{"ID":"cards"}}},"CHILD":{"block":{"type":"js_get_var","id":"lp{-BEw5LI:(3%8=HT#4","fields":{"NAME":"card","PICK_NAME":"__choose__"}}}}}}}}}}}}}}}}}}},"next":{"block":{"type":"js_call","id":"+4Kre*Fo]z3ic3XC/WAp","extraState":{"itemCount":1},"fields":{"NAME":"renderCards","PICK_NAME":"__choose__"},"inputs":{"ARG0":{"block":{"type":"js_string_val","id":"Jn#0)RCs19|_4X!7DF1E","fields":{"VALUE":""}}}},"next":{"block":{"type":"js_listen","id":"U6xxXwHFZKzd|#:Nir/4","fields":{"EVENT":"input","OPTION":"NORMAL"},"inputs":{"ELEM":{"block":{"type":"js_get_by_id","id":",.b!5Axd+Db*1Zl]9O}_","fields":{"ID":"search"}}},"HANDLER":{"block":{"type":"js_call","id":"y$Ty}U$e2Kk2h}{G;EWK","extraState":{"itemCount":1},"fields":{"NAME":"renderCards","PICK_NAME":"__choose__"},"inputs":{"ARG0":{"block":{"type":"js_event_value","id":"@yy/ud)^FGuq`Mj^Qdw+"}}}}}}}}}}}}}]}},"code":"const topics = [''HTML'', ''CSS'', ''JavaScript''];\nfunction renderCards(query) {\n  (document.getElementById(''cards'')).innerHTML = '''';\n  (topics.filter(((name) => {\n    return ((name.toLowerCase()).includes((query.toLowerCase())));\n  }))).forEach(((name) => {\n    const card = (document.createElement(''article''));\n    card.textContent = name;\n    (document.getElementById(''cards'')).appendChild(card);\n  }));\n}\nrenderCards('''');\n(document.getElementById(''search'')).addEventListener(''input'', function(event) {\n  renderCards(event.target.value);\n}, { once: false });"},{"filename":"index.html","initial":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","fields":{},"inputs":{"HTML":{"block":{"type":"head","fields":{},"inputs":{"head_element":{"block":{"type":"title","fields":{"NAME":"My learning page"}}}},"next":{"block":{"type":"body","fields":{},"inputs":{"body_element":{"block":{"type":"heading","fields":{"LEVEL":"1","TEXT":"Find a topic"},"next":{"block":{"type":"label","fields":{"TEXT":"Search ","FOR":"search"},"next":{"block":{"type":"input","fields":{"TYPE":"text","REQUIRED":"FALSE"},"inputs":{"attributes":{"block":{"type":"id","fields":{"NAME":"search"}}}},"next":{"block":{"type":"div","fields":{},"inputs":{"attributes":{"block":{"type":"id","fields":{"NAME":"cards"}}},"CONTENT":{"block":null}},"next":{"block":{"type":"script_js_file","fields":{"FILENAME":"main.js"}}}}}}}}}}}}}}}}}}]}},"solution":{"blocks":{"languageVersion":0,"blocks":[{"type":"html_doctype","fields":{},"inputs":{"HTML":{"block":{"type":"head","fields":{},"inputs":{"head_element":{"block":{"type":"title","fields":{"NAME":"My learning page"}}}},"next":{"block":{"type":"body","fields":{},"inputs":{"body_element":{"block":{"type":"heading","fields":{"LEVEL":"1","TEXT":"Find a topic"},"next":{"block":{"type":"label","fields":{"TEXT":"Search ","FOR":"search"},"next":{"block":{"type":"input","fields":{"TYPE":"text","REQUIRED":"FALSE"},"inputs":{"attributes":{"block":{"type":"id","fields":{"NAME":"search"}}}},"next":{"block":{"type":"div","fields":{},"inputs":{"attributes":{"block":{"type":"id","fields":{"NAME":"cards"}}},"CONTENT":{"block":null}},"next":{"block":{"type":"script_js_file","fields":{"FILENAME":"main.js"}}}}}}}}}}}}}}}}}}]}},"code":"<!DOCTYPE html>\n<html>\n  <head>\n      <title>My learning page</title>\n  </head>\n  <body>\n      <h1>Find a topic</h1>\n        <label for=\"search\">Search </label>\n        <input type=\"text\" placeholder=\"Enter text\" id=\"search\">\n      <div id=\"cards\">\n      </div>\n    <script src=\"main.js\"></script>\n  </body>\n</html>\n"}],"checks":[{"type":"codeIncludes","value":"renderCards","message":"Include the concept demonstrated in this step."}]}'::jsonb;
 begin
 select id into author_id from public.profiles where role='admin' order by created_at limit 1;
 if author_id is null then raise exception 'An administrator is required to own the curriculum.'; end if;
 select id into course_id from public.courses where slug='javascript';
 if course_id is null then insert into public.courses(title,slug,description,color) values('JavaScript','javascript','Learn JavaScript through guided practice and independently reviewed projects.','#4f46e5') returning id into course_id; end if;
 if exists(select 1 from public.topics t where t.course_id=curriculum.course_id and classroom_id is null and title='Reusable functions, arrays and interactive filtering' and description like '[WebbedSite curriculum]%') then return; end if;
 insert into public.topics(course_id,title,description,"order",is_published,slug)
 values(course_id,'Reusable functions, arrays and interactive filtering','[WebbedSite curriculum] Combine a reusable rendering function, a collection and input events into a working filter.',coalesce((select max("order")+1 from public.topics t where t.course_id=curriculum.course_id and t.classroom_id is null),0),true,'release-javascript-advanced') returning id into topic_id;
 foreach kind in array array['lecture','tutorial','quiz','laboratory'] loop
 insert into public.lessons(topics_id,author,title,type,is_published,slug,"order",base_xp,proficiency_tier,mastery_checkpoint,learning_objective,topic_track,required_for_topic)
 values(topic_id,author_id,initcap(kind)||': '||'Reusable functions, arrays and interactive filtering',kind,false,'release-javascript-advanced'||'-'||kind,array_position(array['lecture','tutorial','quiz','laboratory'],kind),50,'advanced',kind in ('quiz','laboratory'),'Combine a reusable rendering function, a collection and input events into a working filter.','core',true) returning id into lesson_id;
 if kind='lecture' then insert into public.lectures(lesson_id,content) values(lesson_id,data->>'lecture');
 elsif kind='laboratory' then insert into public.laboratories(lesson_id,instruction) values(lesson_id,jsonb_build_object('description',data->>'activity','files',(select jsonb_agg(jsonb_build_object('filename',f1->>'filename','blocks_json',f1->'initial')) from jsonb_array_elements(data->'files') f1))::text);
 elsif kind='quiz' then
 insert into public.quizzes(lesson_id,time_limit,passing_score) values(lesson_id,300,ceil(jsonb_array_length(data->'questions')*0.75)::integer) returning id into quiz_id;
 for qu in select value from jsonb_array_elements(data->'questions') loop
 insert into public.questions(quiz_id,text,"order") values(quiz_id,qu->>0,coalesce((select max("order")+1 from public.questions qu1 where qu1.quiz_id=curriculum.quiz_id),1)) returning id into question_id;
 for option_number in 1..jsonb_array_length(qu)-1 loop insert into public.options(question_id,text,is_correct) values(question_id,qu->>option_number,option_number=1); end loop;
 end loop;
 else
 insert into public.tutorials(lesson_id,type) values(lesson_id,'block') returning id into tutorial_id;
 for f in select value from jsonb_array_elements(data->'files') loop
 insert into public.block_tutorial_step_files(tutorial_id,filename,file_type,initial_content_json) values(tutorial_id,f->>'filename',split_part(f->>'filename','.',2),f->'initial');
 end loop;
 for step_number in 1..3 loop
 insert into public.block_tutorial_steps(tutorial_id,instruction,hint,"order",highlight_block_type)
 values(tutorial_id,case step_number when 1 then 'Read the objective: '|| (data->>'objective') || E'
Identify the page elements or selector that the activity will use. Start building the demonstrated concept in blocks.' when 2 then 'Build and connect the core behavior or styling. '||(data->>'concepts') else 'Run the complete project, inspect the generated source and check the stated cases. '||(data->>'activity') end,
 'Use the appropriate language palette. Inspect connections and run the preview after each small change.',step_number,case when 'javascript'='javascript' then 'js_listen' when 'javascript'='css' then 'style_target' else 'heading' end) returning id into step_id;
 for f in select value from jsonb_array_elements(data->'files') loop
 select id into file_id from public.block_tutorial_step_files f1 where f1.tutorial_id=curriculum.tutorial_id and filename=f->>'filename';
 insert into public.block_tutorial_step_expected(step_id,file_id,expected_code,expected_blocks_json,test_cases,require_block_structure)
 values(step_id,file_id,f->>'code',f->'solution',case when f->>'filename'='main.js' then data->'checks' else '[]'::jsonb end,false);
 end loop;
 end loop;
 end if;
 update public.lessons set is_published=true where id=lesson_id;
 end loop;
 end $seed$;